import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.Lq8Lraw_.js";const k=JSON.parse('{"title":"05 分支入门：HEAD 与引用","description":"","frontmatter":{},"headers":[],"relativePath":"guide/basics/05-branch-basics.md","filePath":"guide/basics/05-branch-basics.md","lastUpdated":1792671989000}'),n={name:"guide/basics/05-branch-basics.md"};function p(l,s,d,c,h,o){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="_05-分支入门-head-与引用" tabindex="-1">05 分支入门：HEAD 与引用 <a class="header-anchor" href="#_05-分支入门-head-与引用" aria-label="Permalink to &quot;05 分支入门：HEAD 与引用&quot;">​</a></h1><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>能说明分支本质上是指向提交的可移动指针，并定位 <code>.git/refs/heads</code> 中的对应文件。</li><li>能解释 <code>HEAD</code> 的作用，以及什么情况下会进入游离头指针（detached HEAD）。</li><li>能使用 <code>git branch</code>、<code>git switch</code>、<code>git switch -c</code> 完成分支的创建、切换与删除。</li><li>能写出旧命令 <code>git checkout</code> 与新命令的对应关系。</li><li>能用 ASCII 图推演新建分支、切换分支、提交后指针的移动方向。</li></ul><h2 id="分支只是一个指针" tabindex="-1">分支只是一个指针 <a class="header-anchor" href="#分支只是一个指针" aria-label="Permalink to &quot;分支只是一个指针&quot;">​</a></h2><p>Git 的提交通过父指针串成有向图。分支（branch）不是提交的副本，也不是目录的拷贝，而是一个指向某个提交的引用（ref），文件位于 <code>.git/refs/heads/&lt;branch&gt;</code>，内容就是提交哈希。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main</span></span>
<span class="line"><span> |</span></span>
<span class="line"><span> v</span></span>
<span class="line"><span>* 3f2a1c9 feat: 登录接口</span></span>
<span class="line"><span>* 8b1e0d4 fix: 修复超时</span></span>
<span class="line"><span>* 2a9c7f1 chore: 初始化项目</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .git/refs/heads/main</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3f2a1c9a1b2c3d4e5f60718293a4b5c6d7e8f901</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rev-parse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3f2a1c9a1b2c3d4e5f60718293a4b5c6d7e8f901</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># * main 3f2a1c9 feat: 登录接口</span></span></code></pre></div><p>创建分支只是写入一个包含哈希的小文件，因此几乎零成本。这也是 Git 鼓励「一个任务一个分支」的根本原因。</p><h2 id="head-当前所在的引用" tabindex="-1">HEAD：当前所在的引用 <a class="header-anchor" href="#head-当前所在的引用" aria-label="Permalink to &quot;HEAD：当前所在的引用&quot;">​</a></h2><p><code>HEAD</code> 是一个符号引用（symbolic ref），通常指向当前分支，而不是直接指向提交：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> symbolic-ref</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HEAD</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># refs/heads/main</span></span></code></pre></div><p>当你在 <code>main</code> 上提交时，HEAD 不动，<code>main</code> 指针向前移动到新提交。切换分支时，HEAD 改为指向另一个分支，工作区随之更新。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>提交前：</span></span>
<span class="line"><span>HEAD -&gt; main -&gt; 8b1e0d4</span></span>
<span class="line"><span></span></span>
<span class="line"><span>提交后：</span></span>
<span class="line"><span>HEAD -&gt; main -&gt; 3f2a1c9 -&gt; 8b1e0d4</span></span></code></pre></div><h3 id="游离头指针-detached-head" tabindex="-1">游离头指针（detached HEAD） <a class="header-anchor" href="#游离头指针-detached-head" aria-label="Permalink to &quot;游离头指针（detached HEAD）&quot;">​</a></h3><p>当 HEAD 直接指向某个提交哈希，而不是分支时，就处于 detached HEAD 状态。常见触发方式：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --detach</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8b1e0d4</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># HEAD is now at 8b1e0d4 fix: 修复超时</span></span></code></pre></div><p>也可以检出标签或远程分支的某个提交，效果相同。此时：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HEAD -&gt; 8b1e0d4</span></span>
<span class="line"><span>main -&gt; 3f2a1c9</span></span></code></pre></div><p>工作区显示的是 <code>8b1e0d4</code> 的内容，可以查看、编译、实验，但在此状态下创建的新提交不属于任何分支。一旦切走，这些提交只能通过 reflog 找回。</p><div class="danger custom-block"><p class="custom-block-title">不要在游离 HEAD 上直接开发</p><p>提交后切回 <code>main</code>，会看到 <code>Warning: You are leaving 1 commit behind</code>。正确做法是立即基于当前位置建分支：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rescue/experiment</span></span></code></pre></div><p>这样 HEAD 重新指向分支，已有提交也被纳入引用，不会丢失。</p></div><h2 id="创建、切换与删除分支" tabindex="-1">创建、切换与删除分支 <a class="header-anchor" href="#创建、切换与删除分支" aria-label="Permalink to &quot;创建、切换与删除分支&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                      # 列出本地分支，* 表示当前分支</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># * main</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   feature/login</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -vv</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # 附带上游分支与最后一次提交</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># * main          3f2a1c9 [origin/main] feat: 登录接口</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   feature/login 4c5d6e7 feat: 登录页面</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/login</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 在当前提交上创建分支，但不切换</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/login</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 切换过去</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Switched to branch &#39;feature/login&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/payment</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 创建并切换</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Switched to a new branch &#39;feature/payment&#39;</span></span></code></pre></div><p>删除与重命名：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/login</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Deleted branch feature/login (was 4c5d6e7).</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/experiment</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 强制删除未合并分支</span></span></code></pre></div><p><code>-d</code> 会检查分支是否已合并，未合并时拒绝删除，这是防止误删提交的保护。<code>-D</code> 跳过检查，只应在确认提交已无用或已另行保存时使用。</p><h2 id="新旧命令对照" tabindex="-1">新旧命令对照 <a class="header-anchor" href="#新旧命令对照" aria-label="Permalink to &quot;新旧命令对照&quot;">​</a></h2><p><code>git switch</code> 与 <code>git restore</code> 从 Git 2.23 起用于拆分 <code>git checkout</code> 的职责：前者管分支，后者管文件。旧命令仍然可用，但语义容易混淆。</p><table tabindex="0"><thead><tr><th>旧命令</th><th>新命令</th><th>作用</th></tr></thead><tbody><tr><td><code>git checkout main</code></td><td><code>git switch main</code></td><td>切换分支</td></tr><tr><td><code>git checkout -b feature/x</code></td><td><code>git switch -c feature/x</code></td><td>创建并切换</td></tr><tr><td><code>git checkout &lt;commit&gt;</code></td><td><code>git switch --detach &lt;commit&gt;</code></td><td>进入游离 HEAD</td></tr><tr><td><code>git checkout -- &lt;file&gt;</code></td><td><code>git restore &lt;file&gt;</code></td><td>丢弃工作区修改</td></tr><tr><td><code>git checkout &lt;commit&gt; -- &lt;file&gt;</code></td><td><code>git restore --source=&lt;commit&gt; &lt;file&gt;</code></td><td>取回历史版本文件</td></tr></tbody></table><p>在脚本或旧文档里看到 <code>checkout</code>，先判断它操作的是分支还是文件，再决定替换为哪条新命令。</p><h2 id="指针移动的完整推演" tabindex="-1">指针移动的完整推演 <a class="header-anchor" href="#指针移动的完整推演" aria-label="Permalink to &quot;指针移动的完整推演&quot;">​</a></h2><p>从一个提交开始：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main</span></span>
<span class="line"><span> |</span></span>
<span class="line"><span> v</span></span>
<span class="line"><span>* 2a9c7f1 chore: 初始化项目</span></span></code></pre></div><p>执行 <code>git switch -c feature/login</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>main            feature/login</span></span>
<span class="line"><span> |                    |</span></span>
<span class="line"><span> v                    v</span></span>
<span class="line"><span>* 2a9c7f1 chore: 初始化项目</span></span></code></pre></div><p>两个分支指向同一个提交。随后在 <code>feature/login</code> 上提交两次：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                        HEAD -&gt; feature/login</span></span>
<span class="line"><span>                               |</span></span>
<span class="line"><span>                               v</span></span>
<span class="line"><span>* 8b1e0d4 feat: 登录页面     ← feature/login</span></span>
<span class="line"><span>* 3f2a1c9 feat: 登录接口</span></span>
<span class="line"><span>* 2a9c7f1 chore: 初始化项目   ← main</span></span></code></pre></div><p>执行 <code>git switch main</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>* 8b1e0d4 feat: 登录页面     ← feature/login</span></span>
<span class="line"><span>* 3f2a1c9 feat: 登录接口</span></span>
<span class="line"><span>* 2a9c7f1 chore: 初始化项目   ← HEAD -&gt; main</span></span></code></pre></div><p>工作区回到 <code>main</code> 指向的 <code>2a9c7f1</code>，<code>feature/login</code> 的提交仍然存在于对象库中。再执行 <code>git merge feature/login</code>，<code>main</code> 指针会向前移动，这就是下一篇要讲的快进合并。</p><h2 id="分支命名与清理" tabindex="-1">分支命名与清理 <a class="header-anchor" href="#分支命名与清理" aria-label="Permalink to &quot;分支命名与清理&quot;">​</a></h2><p>企业项目通常用「类型/范围」命名，避免 <code>dev2</code>、<code>zhangsan-test</code> 这类无法判断用途的名字：</p><table tabindex="0"><thead><tr><th>前缀</th><th>用途</th><th>示例</th></tr></thead><tbody><tr><td><code>feature/</code></td><td>新功能</td><td><code>feature/login-sms</code></td></tr><tr><td><code>fix/</code></td><td>缺陷修复</td><td><code>fix/order-amount-zero</code></td></tr><tr><td><code>hotfix/</code></td><td>线上紧急修复</td><td><code>hotfix/payment-timeout</code></td></tr><tr><td><code>release/</code></td><td>发布准备</td><td><code>release/1.4.0</code></td></tr><tr><td><code>chore/</code></td><td>构建、依赖、配置</td><td><code>chore/upgrade-vite</code></td></tr></tbody></table><p>查看分支合并情况，辅助清理：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --merged</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 已合入 main，可以安全删除</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-merged</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 尚未合入，删除前需确认</span></span></code></pre></div><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">游离 HEAD 上的提交会「消失」</p><p>在 detached HEAD 状态提交后直接切换分支，提交不在任何分支上，<code>git log</code> 看不到。用 <code>git reflog</code> 找到哈希后 <code>git switch -c rescue &lt;hash&gt;</code> 可恢复。不要依赖「我记得提交过」。</p></div><div class="warning custom-block"><p class="custom-block-title"><code>-D</code> 会直接丢弃未合并的提交</p><p><code>git branch -d</code> 拒绝删除是有原因的。被删除分支的提交暂时还能通过 reflog 找回，但 reflog 会过期（默认 90 天），并不是长期保险。删除前先确认 <code>git branch --no-merged</code> 的输出。</p></div><div class="tip custom-block"><p class="custom-block-title">分支名不能与已有目录冲突</p><p>Git 把引用存成文件路径，<code>feature</code> 与 <code>feature/login</code> 不能同时存在，因为前者需要是文件、后者需要是目录。命名时直接用 <code>feature/login</code>，不要先建一个叫 <code>feature</code> 的分支。</p></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分支是指向提交的可移动指针，存放在 <code>.git/refs/heads</code>，创建成本极低。</li><li><code>HEAD</code> 通常指向当前分支；直接指向提交时进入 detached HEAD。</li><li><code>git switch</code> 管分支，<code>git restore</code> 管文件，二者替代了 <code>git checkout</code> 的混合语义。</li><li>在分支上提交只移动该分支指针，其他分支保持不动。</li><li>删除分支前用 <code>--merged</code> / <code>--no-merged</code> 判断是否安全。</li></ul><p>分支之间如何汇合，见 <a href="/git-tutorial-site/guide/intermediate/01-branch-merge">06 分支合并与快进</a>。</p>`,51)])])}const g=a(n,[["render",p]]);export{k as __pageData,g as default};
